<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Sorting Visualizer</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    background: #121418;
    color: #e8eaf0;
    font-family: system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 24px 16px 32px;
  }
  h1 { font-size: 1.4rem; margin-bottom: 6px; letter-spacing: 0.3px; }
  p.sub { color: #9aa3b2; font-size: 0.9rem; margin-bottom: 16px; }
  #controls { display: flex; gap: 10px; margin-bottom: 18px; flex-wrap: wrap; justify-content: center; }
  button {
    background: #1f2530;
    color: #e8eaf0;
    border: 1px solid #333c4d;
    border-radius: 8px;
    padding: 9px 18px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: background 0.15s, transform 0.05s;
  }
  button:hover { background: #2a3344; }
  button:active { transform: translateY(1px); }
  button:disabled { opacity: 0.5; cursor: default; }
  #sort { background: #2563eb; border-color: #2563eb; }
  #sort:hover { background: #1d4ed8; }
  #wrap {
    width: min(900px, 96vw);
    background: #181c23;
    border: 1px solid #2a3140;
    border-radius: 12px;
    padding: 16px;
    box-shadow: 0 8px 30px rgba(0,0,0,0.4);
  }
  #bars {
    display: flex;
    align-items: flex-end;
    gap: 2px;
    height: 400px;
    width: 100%;
    background: #0e1116;
    border: 1px solid #262d3a;
    border-radius: 8px;
    padding: 10px;
    overflow: hidden;
  }
  .bar {
    flex: 1 1 0;
    min-width: 2px;
    background: linear-gradient(to top, #2563eb, #60a5fa);
    border-radius: 3px 3px 0 0;
    transition: height 0.08s linear, background 0.08s;
  }
  .bar.comparing {
    background: linear-gradient(to top, #ef4444, #fbbf24);
  }
  .bar.sorted-ok {
    background: linear-gradient(to top, #059669, #34d399);
  }
  #status { margin-top: 10px; color: #9aa3b2; font-size: 0.85rem; text-align: center; min-height: 1.2em; }
</style>
</head>
<body>
<h1>Sorting Visualizer</h1>
<p class="sub">Bubble sort &middot; dark theme &middot; animated bars</p>
<div id="controls">
  <button id="shuffle" type="button">Shuffle</button>
  <button id="sort" type="button">Sort</button>
  <button id="reset" type="button">Reset</button>
</div>
<div id="wrap">
  <div id="bars"></div>
  <div id="status"></div>
</div>
<script>
(function () {
  var DEFAULT_SIZE = 50;
  var data = [];
  var outer = 0;
  var inner = 0;
  var comparing = [];
  var animId = null;
  var statusEl = document.getElementById('status');

  function randomArray(n) {
    var arr = [];
    for (var k = 0; k < n; k++) {
      arr.push(5 + Math.floor(Math.random() * 96));
    }
    // Fisher-Yates shuffle
    for (var i2 = arr.length - 1; i2 > 0; i2--) {
      var j2 = Math.floor(Math.random() * (i2 + 1));
      var t = arr[i2];
      arr[i2] = arr[j2];
      arr[j2] = t;
    }
    return arr;
  }

  function resetSortState() {
    outer = 0;
    inner = 0;
    comparing = [];
  }

  function stopAnim() {
    if (animId !== null) {
      clearInterval(animId);
      animId = null;
    }
    var sb = document.getElementById('sort');
    if (sb) sb.disabled = false;
  }

  function isSorted() {
    for (var k = 0; k < data.length - 1; k++) {
      if (data[k] > data[k + 1]) return false;
    }
    return true;
  }

  function setStatus(msg) {
    if (statusEl) statusEl.textContent = msg;
  }

  function render() {
    var container = document.getElementById('bars');
    container.innerHTML = '';
    var n = data.length;
    if (n === 0) return;
    var max = data[0];
    var min = data[0];
    for (var k = 1; k < n; k++) {
      if (data[k] > max) max = data[k];
      if (data[k] < min) min = data[k];
    }
    var allDone = isSorted();
    for (var idx = 0; idx < n; idx++) {
      var d = document.createElement('div');
      d.className = 'bar';
      if (comparing.length === 2 && (idx === comparing[0] || idx === comparing[1]) && !allDone) {
        d.className += ' comparing';
      } else if (allDone && n > 0) {
        d.className += ' sorted-ok';
      }
      var h;
      if (max === min) {
        h = 100;
      } else if (min >= 0) {
        var m = max === 0 ? 1 : max;
        h = (data[idx] / m) * 100;
      } else {
        h = ((data[idx] - min) / (max - min)) * 100;
      }
      if (h < 0) h = 0;
      if (h > 100) h = 100;
      d.style.height = h + '%';
      d.setAttribute('data-value', String(data[idx]));
      container.appendChild(d);
    }
  }

  function getArray() {
    return data.slice();
  }

  function setArray(a) {
    stopAnim();
    if (!a || typeof a.length !== 'number') {
      data = [];
    } else {
      data = [];
      for (var i = 0; i < a.length; i++) {
        data.push(Number(a[i]));
      }
    }
    resetSortState();
    render();
    if (isSorted()) setStatus('Sorted');
    else setStatus('Array set: ' + data.length + ' elements');
  }

  // One bubble-sort comparison (and possible swap) per call.
  function sortStep() {
    var n = data.length;
    if (n <= 1) {
      comparing = [];
      render();
      setStatus('Sorted');
      return true;
    }
    if (isSorted()) {
      comparing = [];
      render();
      setStatus('Sorted');
      return true;
    }
    if (outer >= n - 1) {
      // Safety: restart passes if somehow not sorted after full cycles
      outer = 0;
      inner = 0;
      if (isSorted()) {
        comparing = [];
        render();
        return true;
      }
    }
    if (inner >= n - outer - 1) {
      inner = 0;
      outer++;
      if (outer >= n - 1) {
        comparing = [];
        render();
        return isSorted();
      }
    }
    // exactly one comparison
    comparing = [inner, inner + 1];
    if (data[inner] > data[inner + 1]) {
      var tmp = data[inner];
      data[inner] = data[inner + 1];
      data[inner + 1] = tmp;
    }
    inner++;
    render();
    if (isSorted()) {
      comparing = [];
      render();
      setStatus('Sorted');
      return true;
    }
    return false;
  }

  function isSortedPublic() {
    return isSorted();
  }

  window.viz = {
    array: getArray,
    setArray: setArray,
    sortStep: sortStep,
    sorted: isSortedPublic
  };

  document.getElementById('shuffle').addEventListener('click', function () {
    stopAnim();
    // shuffle current array in place
    for (var i = data.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      var tt = data[i];
      data[i] = data[j];
      data[j] = tt;
    }
    // if empty, create a fresh random array
    if (data.length === 0) {
      data = randomArray(DEFAULT_SIZE);
    }
    resetSortState();
    render();
    setStatus('Shuffled');
  });

  document.getElementById('reset').addEventListener('click', function () {
    stopAnim();
    var n = data.length || DEFAULT_SIZE;
    data = randomArray(n);
    resetSortState();
    render();
    setStatus('Reset: ' + n + ' elements');
  });

  document.getElementById('sort').addEventListener('click', function () {
    if (isSorted()) {
      comparing = [];
      render();
      setStatus('Already sorted');
      return;
    }
    stopAnim();
    var btn = document.getElementById('sort');
    btn.disabled = true;
    setStatus('Sorting...');
    animId = setInterval(function () {
      var done = sortStep();
      if (done) {
        stopAnim();
        setStatus('Sorted');
      }
    }, 25);
  });

  // init
  data = randomArray(DEFAULT_SIZE);
  resetSortState();
  render();
  setStatus('Ready: ' + data.length + ' elements');
})();
</script>
</body>
</html>
